const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const svgNS='http://www.w3.org/2000/svg';
function rebind(element,handler){if(!element)return null;const clone=element.cloneNode(true);element.replaceWith(clone);clone.addEventListener('click',handler);return clone}
function downloadText(filename,content,type='text/plain;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function enhancedDialog(id,title,body,{wide=false,subtitle='',actions=''}={}){
  closeEnhancedDialog(id);
  const modal=document.createElement('div');modal.className='enhanced-modal';modal.id=id;
  modal.innerHTML=`<section class="enhanced-dialog${wide?' wide':''}" role="dialog" aria-modal="true" aria-label="${title}"><div class="dialog-head"><div><h2>${title}</h2></div><button class="icon-button" data-enhanced-close><i data-icon="x"></i></button></div>${subtitle?`<p class="dialog-subtitle">${subtitle}</p>`:''}<div class="enhanced-dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}</section>`;
  document.body.appendChild(modal);hydrateIcons(modal);
  modal.addEventListener('mousedown',e=>{if(e.target===modal)closeEnhancedDialog(id)});
  $('[data-enhanced-close]',modal).addEventListener('click',()=>closeEnhancedDialog(id));
  return modal;
}
function closeEnhancedDialog(id){document.getElementById(id)?.remove()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$$('.enhanced-modal').forEach(el=>el.remove());$('.column-picker')?.remove();$('.chart-panel.chart-expanded')?.classList.remove('chart-expanded')}});

