function selectWatchGroup(name){
  switchPage('watch');
  $$('[data-watch-group]').forEach(el=>el.classList.toggle('active',el.dataset.watchGroup===name));
  const members=groupMembers[name]||groupMembers['全部账户 · 持仓'];
  $$('#watch-table-body tr').forEach(row=>row.hidden=!members.includes(row.dataset.stock));
  $('.watch-list-toolbar h2').textContent=name;
  $('.watch-list-toolbar>div:first-child>span').textContent=`${members.length} 只显示 · 共 ${$$('[data-watch-group]').find(el=>el.dataset.watchGroup===name)?.querySelector('span:last-child').textContent||members.length} 只`;
  const first=members[0];if(first)selectStock(first);
}
