function cellNumber(text){const normalized=text.replace(/−/g,'-').replace(/,/g,'').trim(),match=normalized.match(/-?\d+(?:\.\d+)?/);if(!match)return NaN;let value=Number(match[0]);if(normalized.includes('万亿'))value*=1e12;else if(normalized.includes('亿'))value*=1e8;else if(normalized.includes('万'))value*=1e4;return value}
$$('.data-table').forEach(table=>{
  $$('thead th',table).forEach(th=>{
    if(th.querySelector('input')||th.textContent.trim()==='')return;th.classList.add('sortable');th.title='点击排序';
    th.addEventListener('click',()=>{
      const index=th.cellIndex,asc=!th.classList.contains('sort-asc'),tbody=$('tbody',table),rows=$$('tr',tbody);
      $$('th',table).forEach(other=>other.classList.remove('sort-asc','sort-desc'));th.classList.add(asc?'sort-asc':'sort-desc');
      rows.sort((a,b)=>{const av=a.cells[index]?.textContent.trim()||'',bv=b.cells[index]?.textContent.trim()||'',an=cellNumber(av),bn=cellNumber(bv);const result=Number.isNaN(an)||Number.isNaN(bn)?av.localeCompare(bv,'zh-CN'):an-bn;return asc?result:-result});
      rows.forEach(row=>tbody.appendChild(row));
    });
  });
});
let activeColumnPicker=null;
function closeColumnPicker(){activeColumnPicker?.remove();activeColumnPicker=null}
function openColumnPicker(button,table){
  closeColumnPicker();const picker=document.createElement('div');picker.className='column-picker';activeColumnPicker=picker;
  const headers=$$('thead th',table);picker.innerHTML=`<div class="popover-head"><strong>显示字段</strong><button>全部恢复</button></div>${headers.map((th,i)=>`<label class="column-option"><input type="checkbox" data-column="${i}" ${i===0?'disabled':''} checked/><span>${th.textContent.trim().replace(/\s+/g,' ')}</span></label>`).join('')}`;
  document.body.appendChild(picker);const rect=button.getBoundingClientRect();picker.style.top=`${Math.min(innerHeight-picker.offsetHeight-12,rect.bottom+7)}px`;picker.style.left=`${Math.max(12,Math.min(innerWidth-230,rect.right-218))}px`;
  $('.popover-head button',picker).addEventListener('click',()=>{$$('input[data-column]',picker).forEach(input=>{input.checked=true;input.dispatchEvent(new Event('change'))})});
  $$('input[data-column]',picker).forEach(input=>input.addEventListener('change',()=>{const index=Number(input.dataset.column);$$('tr',table).forEach(row=>{const cell=row.cells[index];if(cell)cell.style.display=input.checked?'':'none'})}));
  setTimeout(()=>document.addEventListener('mousedown',function close(e){if(!picker.contains(e.target)&&e.target!==button){closeColumnPicker();document.removeEventListener('mousedown',close)}}),0);
}
$$('.watch-list-toolbar .button, .results-actions .button').filter(btn=>btn.textContent.includes('显示字段')).forEach(btn=>btn.addEventListener('click',()=>openColumnPicker(btn,btn.closest('.watch-list-panel,.screen-results').querySelector('.data-table'))));

