const commandInput=$('#command-input'),commandButtons=$$('.command-body>button');
let commandIndex=0;
function visibleCommands(){return commandButtons.filter(btn=>btn.style.display!=='none')}
function markCommand(index){const visible=visibleCommands();if(!visible.length)return;commandIndex=(index+visible.length)%visible.length;commandButtons.forEach(btn=>btn.classList.remove('command-active'));visible[commandIndex].classList.add('command-active');visible[commandIndex].scrollIntoView({block:'nearest'})}
commandInput.addEventListener('input',()=>{const query=commandInput.value.trim().toLowerCase();let count=0;commandButtons.forEach(btn=>{const match=btn.textContent.toLowerCase().includes(query);btn.style.display=match?'':'none';if(match)count++});$('.command-empty')?.remove();if(!count){const empty=document.createElement('div');empty.className='command-empty';empty.textContent=`没有找到“${commandInput.value}”，可尝试股票代码或研究关键词`;$('.command-body').appendChild(empty)}markCommand(0)});
commandInput.addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();markCommand(commandIndex+(e.key==='ArrowDown'?1:-1))}if(e.key==='Enter'){e.preventDefault();visibleCommands()[commandIndex]?.click()}});

