const researchDocs={
  '新易盛':{code:'300502 · SZ',status:'已完成',attitude:'看好',date:'2026/10/28',review:'2027/01/28',concepts:'CPO · 光模块',industry:'通信设备',conclusion:'高速光模块产品竞争力明确，海外算力资本开支仍是核心驱动，需持续跟踪客户集中度。',body:$('.document-body').innerHTML},
  '中际旭创':{code:'300308 · SZ',status:'已完成',attitude:'看好',date:'2026/10/26',review:'2027/01/26',concepts:'CPO · 光模块',industry:'通信设备',conclusion:'规模优势与盈利质量较好，重点跟踪下一代产品迭代节奏和大客户订单兑现。',body:'<h3>一、公司概况</h3><p>公司聚焦高端光通信收发模块，数通市场是主要增长来源。研究重点为高速产品结构、产能利用率和海外客户需求。</p><h3>二、战略与历史</h3><p>通过持续研发和规模化生产进入全球头部客户供应体系，产品速率升级与制造效率是长期竞争力的主要来源。</p><h3>三、竞争格局</h3><table><thead><tr><th>观察维度</th><th>当前判断</th><th>需要验证</th></tr></thead><tbody><tr><td>规模制造</td><td>交付能力较强</td><td>扩产节奏</td></tr><tr><td>产品结构</td><td>高速产品占比提升</td><td>下一代产品进度</td></tr></tbody></table><h3>四、风险与结论</h3><ul><li>行业价格竞争加剧。</li><li>主要客户资本开支波动。</li></ul><p><strong>结论：</strong>继续作为光模块核心跟踪标的，复查订单、产能与毛利率。</p>'},
  '腾讯控股':{code:'00700 · HK',status:'待研究',attitude:'中性',date:'尚未完成',review:'2026/12/15',concepts:'互联网平台',industry:'软件服务',conclusion:'游戏与广告基本盘稳健，AI 投入回报仍需进一步验证。',body:'<h3>研究提纲</h3><p>当前处于资料整理阶段，暂不形成最终结论。</p><h3>一、公司概况</h3><p>业务覆盖社交、游戏、广告、金融科技与企业服务。现有判断主要基于游戏与广告业务的稳定性。</p><h3>二、待验证问题</h3><ul><li>AI 投入对产品和商业化的实际贡献。</li><li>游戏管线与海外业务持续性。</li><li>资本配置和股东回报。</li></ul><h3>三、下一步</h3><p>核对最新年报与业绩会材料后，再完成竞争格局和估值部分。</p>'},
  '苹果':{code:'AAPL · US',status:'待研究',attitude:'未设态度',date:'尚未完成',review:'未设置',concepts:'消费电子',industry:'硬件设备',conclusion:'尚未形成研究结论。',body:'<div class="account-tab-placeholder"><h3>研究尚未开始</h3><p>默认提纲已准备好：公司概况、战略、历史、竞争格局、风险、结论。</p><p>可在外部完成研究后导入 Markdown 或 Word，并将 PDF 作为附件保存。</p></div>'},
  '招商银行':{code:'600036 · SH',status:'已完成',attitude:'看好',date:'2026/10/18',review:'2027/01/18',concepts:'高股息',industry:'银行',conclusion:'高股息底仓，零售业务优势明显，后续重点关注资产质量与分红持续性。',body:'<h3>一、公司概况</h3><p>零售银行基础较好，客户基础和财富管理业务是主要差异化来源。</p><h3>二、核心判断</h3><p>作为高股息底仓跟踪，重点不是短期价格，而是资产质量、净息差与分红能力的持续性。</p><h3>三、风险与结论</h3><ul><li>净息差继续承压。</li><li>零售资产质量波动。</li><li>分红比例变化。</li></ul><p><strong>结论：</strong>保留长期跟踪，财报后重点更新资产质量与分红数据。</p>'}
};
let currentResearch='新易盛';
function renderResearch(name){
  const doc=researchDocs[name];if(!doc)return;currentResearch=name;
  const title=$('.document-head .stock-title');$('h2',title).textContent=name;$('span:not(.research-state)',title).textContent=doc.code;const state=$('.research-state',title);state.textContent=doc.status;state.className=`research-state ${doc.status==='已完成'?'done':doc.status==='待研究'?'doing':'todo'}`;
  $('.research-conclusion p').textContent=doc.conclusion;
  const conclusionMeta=$$('.research-conclusion>div>span');conclusionMeta[0].textContent=doc.attitude;conclusionMeta[0].className=doc.attitude==='看好'?'attitude-positive':'attitude-neutral';conclusionMeta[1].textContent=doc.status==='已完成'?`研究完成于 ${doc.date}`:doc.status;conclusionMeta[2].textContent=`下次复查 ${doc.review}`;
  $('.document-body').innerHTML=doc.body;
  const sideValues=$$('.research-side dl dd');sideValues[0].innerHTML=`<span class="research-state ${doc.status==='已完成'?'done':doc.status==='待研究'?'doing':'todo'}">${doc.status}</span>`;sideValues[1].textContent=doc.attitude;sideValues[2].textContent=doc.concepts;sideValues[3].textContent=doc.industry;
  const attachments=$$('.attachment strong');attachments[0].textContent=`${name}研究底稿.pdf`;attachments[1].textContent='2026Q3 财报摘要.md';
  $('.document-body').removeAttribute('contenteditable');
}
$$('.research-list-item').forEach(item=>item.addEventListener('click',()=>renderResearch($('strong',item).textContent)));
