function filterResearch(){const query=researchSearch.value.trim().toLowerCase(),status=$('.research-toolbar .filter-chip.active').textContent.trim().replace(/\d+/g,'').trim();$$('.research-list-item').forEach(item=>{const textMatch=item.textContent.toLowerCase().includes(query),statusMatch=status==='全部'||$('.research-state',item).textContent===status;item.hidden=!(textMatch&&statusMatch)})}
researchSearch.addEventListener('input',filterResearch);$$('.research-toolbar .filter-chip').forEach(chip=>chip.addEventListener('click',filterResearch));
