rebind(exportResearchButton,()=>{const doc=researchDocs[currentResearch],body=$('.document-body').innerText;downloadText(`${currentResearch}-研究档案.md`,`# ${currentResearch} · 研究档案\n\n> ${doc.conclusion}\n\n- 状态：${doc.status}\n- 态度：${doc.attitude}\n- 研究完成：${doc.date}\n- 下次复查：${doc.review}\n\n${body}`,'text/markdown;charset=utf-8');toast('当前研究档案已导出为 Markdown')});
const importResearchButton=$$('#page-research .heading-actions .button').find(btn=>btn.textContent.includes('导入'));
