function conditionParts(chip){return{label:$('span',chip)?.textContent||'',value:$('strong',chip)?.textContent||''}}
function filteredScreenStocks(){let result=[...screenStocks];$$('.condition-chip').forEach(chip=>{const{label,value}=conditionParts(chip),number=cellNumber(value);if(label.includes('股息率'))result=result.filter(s=>s.dividend>=number);else if(label==='总市值'){if(value.includes('–')||value.includes('—')){const nums=value.match(/\d+(?:\.\d+)?/g)?.map(Number)||[];result=result.filter(s=>s.cap>=nums[0]&&s.cap<=nums[1])}else result=result.filter(s=>s.cap>=Number(value.match(/\d+(?:\.\d+)?/)[0]))}else if(label.includes('ROE'))result=result.filter(s=>s.roe>=number);else if(label.includes('净利率'))result=result.filter(s=>s.net>=number);else if(label.includes('资产负债率'))result=result.filter(s=>s.debt<=number);else if(label.includes('属于')&&!label.includes('不属于')){const values=value.split(/或|\//).map(v=>v.trim()).filter(Boolean);result=result.filter(s=>values.some(v=>s.industry.includes(v)||(v==='公用事业'&&s.industry==='电力')||s.concepts.includes(v)))}else if(label.includes('不属于')){const values=value.split(/或|\//).map(v=>v.trim()).filter(Boolean);result=result.filter(s=>!values.some(v=>s.industry.includes(v)||s.concepts.includes(v)))}});return result}
function resultRow(stock){const cls=stock.status==='已完成'?'done':stock.status==='待研究'?'doing':stock.status==='待研究'?'todo':'none';return`<tr data-result-stock="${stock.name}"><td><input type="checkbox" aria-label="选择 ${stock.name}"/></td><td><strong>${stock.name}</strong><small>${stock.code} <span class="research-state ${cls}">${stock.status}</span></small></td><td>${stock.industry}</td><td class="num">${stock.cap>=10000?(stock.cap/10000).toFixed(2)+' 万亿':stock.cap.toLocaleString()+' 亿'}</td><td class="num strong">${stock.dividend.toFixed(2)}%</td><td class="num">${stock.roe.toFixed(2)}%</td><td class="num">${stock.net.toFixed(2)}%</td><td class="num ${stock.today>=0?'up':'down'}">${stock.today>=0?'+':'−'}${Math.abs(stock.today).toFixed(2)}%</td><td class="${stock.conclusion?'conclusion-cell':'muted-text'}">${stock.conclusion||'尚未形成研究结论'}</td></tr>`}
function runEnhancedScreen(notify=true){const rows=filteredScreenStocks(),tbody=$('.results-table tbody');tbody.innerHTML=rows.length?rows.map(resultRow).join(''):'<tr><td colspan="9"><div class="group-empty">没有符合当前条件的示例股票，可减少一个条件后重试。</div></td></tr>';$('.hit-count').textContent=rows.length;$('.table-pagination>span').textContent=`第 1–${rows.length} 只，共 ${rows.length} 只`;$('.table-pagination>div').innerHTML='<button disabled>上一页</button><button class="active">1</button><button disabled>下一页</button>';$('.batch-bar>span').innerHTML='已选择 <b>0</b> 只';$('.batch-bar input').checked=false;if(notify)toast(`筛选完成：当前显示 ${rows.length} 只符合条件的股票`)}
